import{_ as o,l as i,o as e,c as n,v as r,p as l,x as s,d as c,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"ARM 对 RISC-V","description":"","frontmatter":{"title":"ARM 对 RISC-V","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arm-vs-riscv.md","filePath":"cs/arm-vs-riscv.md","lastUpdated":1789023840000}'),R={name:"cs/arm-vs-riscv.md"};function S(C,a,p,h,I,V){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="arm-对-risc-v" tabindex="-1">ARM 对 RISC-V <a class="header-anchor" href="#arm-对-risc-v" aria-label="Permalink to &quot;ARM 对 RISC-V&quot;">​</a></h1><div class="epigraph"><p>两者都是定长 load/store RISC；差别在条件码、压缩、向量、特权命名与授权模式，而不是「一个 RISC 一个不是」。</p><footer>—— 据 ARM Architecture Reference Manual；The RISC-V Instruction Set Manual；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/aarch64-isa">上一课</a>钉了 A64。<a href="/cs/riscv-int-isa">RISC-V 整数</a> 已是本栏主干。缺口是<strong>对照表</strong>：避免后课原子、fence、页表各说各话时读者以为在学第三种哲学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>相同：运算在寄存器、访存单独、定长基础指令、特权与用户分离。不同：ARM 用 NZCV 与条件分支编码；RISC-V 比较结果进通用寄存器再分支。ARM 商业授权核；RISC-V 开放 ISA、核多家。压缩：ARM 有历史 Thumb，A64 不定长；RISC-V <code>C</code> 扩展 16 位混长（后课）。向量：ARM SVE 与 RISC-V RVV 都是可变长，后课分讲。缺口不是再介绍 A64 寄存器，而是这些<strong>选择的组成后果</strong>。</p><p>页表：ARM 多级与 ASIDs；RISC-V Sv39 后课。虚拟化：ARM EL2 vs RISC-V H 扩展。</p><h3 id="对照不是「谁更快」" tabindex="-1">对照不是「谁更快」 <a class="header-anchor" href="#对照不是「谁更快」" aria-label="Permalink to &quot;对照不是「谁更快」&quot;">​</a></h3><p>性能是微结构、工艺、<a href="/cs/dennard-power-wall">功耗墙</a> 与编译器。ISA 对照课不宣布基准冠军。把课写成选购指南，会滑出系统栈。</p><p><span class="marginnote">两份官方手册 + CA:AQA 的 RISC 章节。本课用差异点列表，不抄指令全表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列一张心智表：寄存器数、零寄存器、链接寄存器（<code>x30</code> vs <code>ra</code>）、栈指针是否特殊、系统调用指令（<code>svc</code> vs <code>ecall</code>）、内存模型（ARM 弱、RISC-V 弱，fence 课）。ABI：AAPCS64 vs RISC-V psABI，最后一课收。</p>',11)),(e(),l(A,null,{default:s(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMM%5B%22%E5%AE%9A%E9%95%BF%20load%2Fstore%22%5D%20--%3E%20ARM%5B%22NZCV%20%2F%20EL%20%2F%20GIC%22%5D%0A%20%20COMM%20--%3E%20RV%5B%22GPR%20%E6%AF%94%E8%BE%83%20%2F%20%E7%89%B9%E6%9D%83%20CSR%20%2F%20PLIC%22%5D%0A%20%20ARM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8E%9F%E5%AD%90%20LR%2FSC%20%E4%B8%8E%20CAS%22%5D%0A%20%20RV%20--%3E%20LATER%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>教学 CPU：RISC-V 更易画单周期；ARM 教材同样可画，字段不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原子：ARM 有 <code>ldxr/stxr</code> 与后来的 LSE <code>cas</code>；RISC-V <code>A</code> 扩展 LR/SC 与 AMO。下一课专讲。SIMD 再下一组。本课防止「ARM=CISC」的谣言（那是 x86）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较授权费，不预测生态。不把 MIPS/POWER 拉进来冲淡。不写 DSP 定点指令全集。</p><p>后课默认：ARM 与 RISC-V 同属 RISC 家族；差异在条件码、压缩、特权与扩展哲学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>都是定长 load/store；x86 才是变长 CISC 外壳。</li><li>条件码 vs 比较进寄存器；特权命名不同。</li><li>速度不由本课裁定。</li><li>出处：ARM ARM；RISC-V ISA Manual；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const M=o(R,[["render",S]]);export{E as __pageData,M as default};
